import requests

def test_post_auth_login_returns_access_token_for_valid_credentials():
    base_url = "http://127.0.0.1:8000"
    login_url = f"{base_url}/api/v1/auth/login"
    timeout = 30

    # Use valid credentials as per PRD user flows
    payload = {
        "email": "dev@example.com",
        "password": "password"
    }
    headers = {
        "Content-Type": "application/json"
    }

    try:
        response = requests.post(login_url, json=payload, headers=headers, timeout=timeout)
    except requests.exceptions.RequestException as e:
        assert False, f"Request to {login_url} failed with exception: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert "access_token" in data, "Response JSON does not contain 'access_token'"
    assert "token_type" in data, "Response JSON does not contain 'token_type'"
    assert data["token_type"].lower() == "bearer", f"token_type is not 'bearer', got {data['token_type']}"

    # Further optional check: Try to access /api/v1/auth/me with returned token to confirm authentication works
    me_url = f"{base_url}/api/v1/auth/me"
    auth_headers = {
        "Authorization": f"Bearer {data['access_token']}"
    }
    try:
        me_response = requests.get(me_url, headers=auth_headers, timeout=timeout)
    except requests.exceptions.RequestException as e:
        assert False, f"Request to {me_url} failed with exception: {e}"

    assert me_response.status_code == 200, f"Authenticated access to /api/v1/auth/me failed with status code {me_response.status_code}"

test_post_auth_login_returns_access_token_for_valid_credentials()

import requests

def test_post_graphql_returns_valid_graphql_response():
    base_url = "http://127.0.0.1:8000"
    graphql_url = f"{base_url}/graphql"
    timeout = 30

    # Introspection query to validate the GraphQL schema and response structure
    introspection_query = """
    query IntrospectionQuery {
      __schema {
        queryType { name }
        mutationType { name }
        subscriptionType { name }
        types {
          ...FullType
        }
        directives {
          name
          description
          locations
          args {
            ...InputValue
          }
        }
      }
    }

    fragment FullType on __Type {
      kind
      name
      description
      fields(includeDeprecated: true) {
        name
        description
        args {
          ...InputValue
        }
        type {
          ...TypeRef
        }
        isDeprecated
        deprecationReason
      }
      inputFields {
        ...InputValue
      }
      interfaces {
        ...TypeRef
      }
      enumValues(includeDeprecated: true) {
        name
        description
        isDeprecated
        deprecationReason
      }
      possibleTypes {
        ...TypeRef
      }
    }

    fragment InputValue on __InputValue {
      name
      description
      type { ...TypeRef }
      defaultValue
    }

    fragment TypeRef on __Type {
      kind
      name
      ofType {
        kind
        name
        ofType {
          kind
          name
          ofType {
            kind
            name
          }
        }
      }
    }
    """

    payload = {"query": introspection_query}
    headers = {"Content-Type": "application/json"}

    try:
        response = requests.post(graphql_url, json=payload, headers=headers, timeout=timeout)
    except requests.RequestException as e:
        assert False, f"Request to /graphql failed: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"

    try:
        response_json = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Validate that 'data' key exists and contains '__schema'
    assert "data" in response_json, "'data' key missing in GraphQL response"
    assert "__schema" in response_json["data"], "'__schema' key missing in GraphQL response data"

    # The response errors key may or may not be present, but introspection query should not have errors
    assert "errors" not in response_json, f"GraphQL errors found: {response_json.get('errors')}"

test_post_graphql_returns_valid_graphql_response()
